import os
import hashlib
import shutil
from datetime import datetime

current_dir = '.'

# Get all jpg files
files = []
for f in os.listdir(current_dir):
    if f.lower().endswith('.jpg'):
        files.append(f)

print(f"Found {len(files)} .jpg files")

# Calculate MD5 hash for each file and get modification time
file_info = {}
for f in files:
    filepath = os.path.join(current_dir, f)
    md5_hash = hashlib.md5()
    with open(filepath, 'rb') as file:
        for chunk in iter(lambda: file.read(4096), b''):
            md5_hash.update(chunk)
    file_hash = md5_hash.hexdigest()

    mtime = os.path.getmtime(filepath)
    mtime_str = datetime.fromtimestamp(mtime).strftime('%Y-%m-%d_%H%M')

    file_info[f] = {
        'hash': file_hash,
        'mtime': mtime_str,
        'mtime_obj': datetime.fromtimestamp(mtime),
        'path': filepath
    }

# Group by hash
hash_groups = {}
for fname, info in file_info.items():
    h = info['hash']
    if h not in hash_groups:
        hash_groups[h] = []
    hash_groups[h].append(fname)

# Decide which duplicate to keep (keep the one without -copy suffix)
def choose_winner(group):
    # Sort: prefer files without -copy, then without (1), then alphabetically
    def sort_key(f):
        if '-copy' in f:
            return (1, f)
        elif '(1)' in f:
            return (2, f)
        else:
            return (0, f)
    return min(group, key=sort_key)

# Identify duplicates and winners
winners = {}
duplicates_to_delete = []
for h, group in hash_groups.items():
    if len(group) > 1:
        winner = choose_winner(group)
        winners[winner] = h
        for f in group:
            if f != winner:
                duplicates_to_delete.append(f)
    else:
        winners[os.path.join(current_dir, f)] = file_info[f]['hash']

print(f"\n=== DUPLICATES TO DELETE ({len(duplicates_to_delete)} files) ===")
for f in sorted(duplicates_to_delete):
    print(f"  Deleting: {f}")

# Now process unique files - rename and move
print("\n=== RENAMING AND MOVING FILES ===")
for f in sorted(file_info.keys()):
    if f in duplicates_to_delete:
        continue

    info = file_info[f]
    year = info['mtime_obj'].year
    month = info['mtime_obj'].month

    # Create year/month directory
    target_dir = os.path.join(current_dir, f"{year}/{month}")
    os.makedirs(target_dir, exist_ok=True)

    # New filename: YYYY-MM-DD_HHMM.jpg
    new_filename = f"{info['mtime']}.jpg"
    target_path = os.path.join(target_dir, new_filename)

    # Move and rename
    src_path = os.path.join(current_dir, f)
    shutil.move(src_path, target_path)

    print(f"  Moved: {f} -> {target_dir}/{new_filename}")

print(f"\nDone! Deleted {len(duplicates_to_delete)} duplicates, renamed {len(file_info) - len(duplicates_to_delete)} files.")

